/**
 * A cicatrização de feridas — o corte fechando em cinco fases.
 *
 * O slider é tempo, e o texto do renderizador já nomeia a fase. O que faltava é
 * VER: o corte que se abre na pele, o coágulo que o tampa, as células de defesa
 * que chegam, o tecido novo que sobe do fundo e, no fim, a linha clara da
 * cicatriz. Cada fase acrescenta uma camada — nenhuma apaga a anterior, que é
 * como o reparo funciona de verdade.
 *
 * A pele está em CORTE, vista de lado: epiderme, derme e o vaso que se rompeu.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Os limiares do renderizador, e o nome curto de cada fase. */
const FASES: readonly (readonly [number, string])[] = [
  [0, 'Corte'],
  [12, 'Hemostasia'],
  [38, 'Inflamação'],
  [62, 'Proliferação'],
  [88, 'Remodelação'],
];

const PELE = '#eabf96';
const PELE_FUNDA = '#d8a578';
const DERME = '#e8b9ae';
const SANGUE = '#b4342f';
const COAGULO = '#7d2420';

/** Pseudoaleatório estável: a mesma célula no mesmo lugar a cada quadro. */
function semente(i: number): number {
  return (Math.sin(i * 12.9898) * 43758.5453) % 1;
}

const cicatrizacao: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, tempo: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const t = limitar(numeroDe(valores, 't', 0), 0, 100);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'O reparo em cinco fases, uma sobre a outra');

    // ── A pele em corte ───────────────────────────────────────────────────
    const x0 = L * 0.06;
    const x1 = L * 0.94;
    const yTopo = A * 0.24;
    const yFundo = A * 0.68;
    const alturaEpiderme = (yFundo - yTopo) * 0.24;

    ctx.save();
    ctx.beginPath();
    ctx.roundRect(x0, yTopo, x1 - x0, yFundo - yTopo, 6);
    ctx.clip();

    ctx.fillStyle = DERME;
    ctx.fillRect(x0, yTopo, x1 - x0, yFundo - yTopo);
    ctx.fillStyle = PELE;
    ctx.fillRect(x0, yTopo, x1 - x0, alturaEpiderme);
    ctx.fillStyle = PELE_FUNDA;
    ctx.fillRect(x0, yTopo + alturaEpiderme - 2, x1 - x0, 2.5);

    // O vaso sanguíneo que o corte atravessa.
    const yVaso = yTopo + (yFundo - yTopo) * 0.72;
    ctx.strokeStyle = SANGUE;
    ctx.lineWidth = Math.max(3, A * 0.016);
    ctx.beginPath();
    ctx.moveTo(x0, yVaso);
    ctx.lineTo(x1, yVaso);
    ctx.stroke();

    // ── O corte, que se fecha com o tempo ─────────────────────────────────
    const cx = (x0 + x1) / 2;
    const aberturaMaxima = (x1 - x0) * 0.11;
    // Fecha entre a proliferação e a remodelação; antes disso segue escancarado.
    const fechamento = limitar((t - 55) / 40, 0, 1);
    const abertura = aberturaMaxima * (1 - fechamento);
    const fundoCorte = yTopo + (yFundo - yTopo) * (0.78 - 0.35 * fechamento);

    const desenharCunha = (largura: number, fundo: number): void => {
      ctx.beginPath();
      ctx.moveTo(cx - largura, yTopo - 4);
      ctx.lineTo(cx + largura, yTopo - 4);
      ctx.lineTo(cx, fundo);
      ctx.closePath();
    };

    if (abertura > 0.6) {
      desenharCunha(abertura, fundoCorte);
      ctx.fillStyle = cor.fundo;
      ctx.fill();
    }

    // Fase 2 em diante: o coágulo tampa a fenda.
    if (t >= 12) {
      const opacidade = limitar((t - 12) / 20, 0, 1);
      ctx.save();
      ctx.globalAlpha = opacidade * (t < 88 ? 1 : limitar((100 - t) / 12, 0.25, 1));
      desenharCunha(Math.max(abertura, aberturaMaxima * 0.35), fundoCorte);
      ctx.fillStyle = COAGULO;
      ctx.fill();
      ctx.restore();
    }

    // Fase 3: as células de defesa acorrem à área.
    if (t >= 38) {
      const quantas = Math.round(limitar((t - 38) / 24, 0, 1) * 14);
      for (let i = 0; i < quantas; i++) {
        const desvio = (semente(i) - 0.5) * (x1 - x0) * 0.34;
        const altura = yTopo + (yFundo - yTopo) * (0.3 + Math.abs(semente(i + 40)) * 0.55);
        const flutua = Math.sin(tempo * 2 + i) * 2;
        disco(
          ctx,
          cx + desvio,
          altura + flutua,
          Math.max(2.5, A * 0.011),
          'rgb(240 248 255 / 85%)',
        );
      }
    }

    // Fase 4: o tecido novo sobe do fundo do ferimento.
    if (t >= 62) {
      const preenchido = limitar((t - 62) / 30, 0, 1);
      ctx.save();
      ctx.globalAlpha = 0.75;
      ctx.fillStyle = '#e2a49a';
      ctx.beginPath();
      ctx.moveTo(cx - aberturaMaxima * 1.1, fundoCorte);
      ctx.lineTo(cx + aberturaMaxima * 1.1, fundoCorte);
      ctx.lineTo(cx + aberturaMaxima * 0.9, fundoCorte - (fundoCorte - yTopo) * preenchido);
      ctx.lineTo(cx - aberturaMaxima * 0.9, fundoCorte - (fundoCorte - yTopo) * preenchido);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    // Fase 5: a cicatriz — a linha clara que fica.
    if (t >= 88) {
      const nitidez = limitar((t - 88) / 12, 0, 1);
      ctx.save();
      ctx.globalAlpha = nitidez;
      ctx.strokeStyle = '#f6ddc8';
      ctx.lineWidth = Math.max(2.5, A * 0.013);
      ctx.beginPath();
      ctx.moveTo(cx, yTopo);
      ctx.lineTo(cx, yTopo + alturaEpiderme * 1.6);
      ctx.stroke();
      ctx.restore();
    }

    ctx.restore();

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(x0, yTopo, x1 - x0, yFundo - yTopo, 6);
    ctx.stroke();

    // ── A trilha das fases ────────────────────────────────────────────────
    const miudo = limitar(A * 0.03, 8, 11);
    const yTrilha = A * 0.79;
    const altura = limitar(A * 0.035, 6, 11);

    retangulo(ctx, x0, yTrilha, x1 - x0, altura, altura / 2, cor.palha, cor.trilho, 1);
    retangulo(
      ctx,
      x0,
      yTrilha,
      ((x1 - x0) * t) / 100,
      altura,
      altura / 2,
      ok ? cor.verde : cor.azul,
    );

    let nome = 'Corte';
    for (const [inicio, rotulo] of FASES) {
      const px = x0 + ((x1 - x0) * inicio) / 100;
      if (t >= inicio) nome = rotulo;

      if (inicio > 0) {
        ctx.strokeStyle = cor.trilho;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(px, yTrilha - 3);
        ctx.lineTo(px, yTrilha + altura + 3);
        ctx.stroke();
      }
    }

    texto(ctx, nome.toUpperCase(), L / 2, yTrilha - miudo * 1.5, miudo * 1.2, {
      cor: ok ? cor.verde : cor.texto,
      peso: 800,
    });
    texto(ctx, `${Math.round(t)}%`, x1, yTrilha + altura + miudo * 1.3, miudo, {
      cor: cor.fraco,
      peso: 700,
      alinhamento: 'right',
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Reparo completo: fica a cicatriz ✔',
      'Avance o tempo e veja cada fase entrar em cena.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default cicatrizacao;
